PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

// -----------------------------------------------------------------------------
// Kernel: compute_norm
//   atomic‑adds per‑row sum of squares (float32) into norm[row].
// -----------------------------------------------------------------------------
.visible .entry compute_norm(
    .param .u64 x_ptr,
    .param .u64 norm_ptr
)
{
    .reg .pred   %p0;
    .reg .u32    %tid_x;
    .reg .u32    %bid_x;
    .reg .u32    %bid_y;
    .reg .u64    %x;
    .reg .u64    %norm;
    .reg .u64    %addr;
    .reg .f16    %xh;
    .reg .f32    %xf;
    .reg .f32    %sq;
    .reg .u32    %col;
    .reg .u32    %dim;
    .reg .u64    %row_off;
    .reg .u64    %idx64;

    // load parameters
    ld.param.u64    %x,    [x_ptr];
    ld.param.u64    %norm, [norm_ptr];

    // thread / block indices
    mov.u32         %tid_x, %tid.x;
    mov.u32         %bid_x, %ctaid.x;
    mov.u32         %bid_y, %ctaid.y;

    // constant dimensions (hard‑coded from the reference)
    mov.u32         %dim, 65535;

    // column index handled by this thread
    mul.lo.u32      %col, %bid_x, 256;
    add.u32         %col, %col, %tid_x;

    // if out‑of‑range, exit
    setp.ge.u32     %p0, %col, %dim;
    @%p0 bra        DONE;

    // linear index (row * dim + col) * sizeof(half)
    // row_offset = row * dim
    mul.wide.u32    %row_off, %bid_y, %dim;
    // add column
    add.u64         %idx64, %row_off, %col;
    // byte offset = (row*dim + col) * 2
    mul.wide.u32    %addr, %idx64, 2;
    add.u64         %addr, %addr, %x;

    // load half, promote to float, square
    ld.global.f16   %xh, [%addr];
    cvt.f32.f16     %xf, %xh;
    mul.f32         %sq, %xf, %xf;

    // atomic add to norm[row] (float32)
    mul.wide.u32    %row_off, %bid_y, 4;          // row * sizeof(float)
    add.u64         %addr, %norm, %row_off;
    atom.global.add.f32 %sq, [%addr], %sq;

DONE:
    ret;
}

