    mul.f32         %outf, %xf, %inv_norm;

    // ----- write half result -----
    cvt.rn.f16.f32  %yh, %outf;
    mul.wide.u32    %addr_y, %idx64, 2;
    add.u64         %addr_y, %addr_y, %y;
    st.global.f16   [%addr_y], %yh;

