import torch
import torch.nn as nn

# The harness is assumed to provide these functions:
#   ptx_load(source: str) -> module_handle
#   ptx_launch(module, kernel_name: str, grid: tuple, block: tuple, args: list)
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.ptx_module = ptx_load(PTX_SOURCE)
        self.batch = 32768
        self.dim   = 65535

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16
        out  = torch.empty_like(x)
        norm = torch.empty(self.batch, dtype=torch.float32, device=x.device)

        grid  = ((self.dim + 255) // 256, self.batch, 1)   # (gridX, gridY, 1)
        block = (256, 1, 1)

        # 1) compute per‑row L2 norm (squared sum)
        ptx_launch(self.ptx_module,
                    "compute_norm",
                    grid, block,
                    [x.data_ptr(), norm.data_ptr()])

        # 2) normalise each element
        ptx_launch(self.ptx_module,
                    "normalize",
                    grid, block,
                    [x.data_ptr(), norm.data_ptr(), out.data_ptr()])

        return out
